/* @lc app=leetcode id=1982 lang=kotlin */ class Solution { fun recoverArray(n: Int, sums: IntArray): IntArray = generateSequence(sums.sorted() to listOf<Int>()) { (s, res) -> if (res.size == n) null else (s[1] - s[0]).let { d -> s.groupingBy { it }.eachCount().toMutableMap().let { cnt -> s.filter { x -> (cnt[x] ?: 0) > 0 && true.also { cnt[x] = cnt[x]!! - 1 }.also { cnt[x + d] = (cnt[x + d] ?: 0) - 1 } } }.let { a -> if (0 in a) a to res + d else a.map { it + d } to res + (-d) } } }.last().second.toIntArray() }